/* Production hardening v2: background notifications, complete entity sync, caregiver alerts and audit-safe access. */
(function(){
  'use strict';
  const C=window.CCNER_CONFIG||{};
  const LOCAL_QUEUE='ccner-p1-sync';
  const LOCAL_REMINDERS='ccner-p1-reminders';
  const LOCAL_TASKS='ccner-p1-tasks';
  let sb=null,user=null,connecting=null;
  const read=(k,d)=>{try{const v=JSON.parse(localStorage.getItem(k)||'null');return v==null?d:v}catch(_){return d}};
  const write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch(_){return false}};
  const esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
  const uuid=()=>crypto.randomUUID?crypto.randomUUID():([1e7]+-1e3+-4e3+-8e3+-1e11).replace(/[018]/g,c=>(c^crypto.getRandomValues(new Uint8Array(1))[0]&15>>c/4).toString(16));
  const now=()=>new Date().toISOString();
  const reminders=()=>Array.isArray(read(LOCAL_REMINDERS,[]))?read(LOCAL_REMINDERS,[]):[];
  const tasks=()=>Array.isArray(read(LOCAL_TASKS,[]))?read(LOCAL_TASKS,[]):[];
  const saveReminders=v=>write(LOCAL_REMINDERS,v);
  const saveTasks=v=>write(LOCAL_TASKS,v);
  const queue=()=>Array.isArray(read(LOCAL_QUEUE,[]))?read(LOCAL_QUEUE,[]):[];
  const saveQueue=v=>write(LOCAL_QUEUE,v.slice(-500));
  const classify=title=>{const t=String(title||'').toLowerCase();if(/medicine|medication|tablet|pill|dose/.test(t))return'medicine';if(/water|hydration|drink/.test(t))return'hydration';if(/appointment|doctor|hospital|clinic|medical/.test(t))return'appointment';if(/walk|bath|breakfast|tea|exercise|routine|activity|task/.test(t))return'daily_activity';return'general'};
  const clientId=(x,prefix)=>x.client_id||x.clientId||x.id||`${prefix}-${uuid()}`;

  function injectStyle(){if(document.getElementById('hardeningStyle'))return;const s=document.createElement('style');s.id='hardeningStyle';s.textContent=`.ph-card{background:#fff;border:1px solid #eadfd6;border-radius:18px;padding:15px;margin:10px 0}.ph-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 0;border-bottom:1px solid #eee4db}.ph-row:last-child{border-bottom:0}.ph-badge{display:inline-flex;padding:5px 9px;border-radius:999px;background:#f0e7ff;font-size:.72rem;font-weight:800}.ph-alert{padding:12px 14px;border-radius:14px;background:#fff3e8;border:1px solid #f0d1b5;margin:8px 0}.ph-alert.urgent{background:#fff0f0;border-color:#efb7b7}.ph-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.ph-btn{border:0;border-radius:12px;padding:10px 13px;background:#4f3a2d;color:#fff;font-weight:800;cursor:pointer}.ph-btn.secondary{background:#fff;color:#4f3a2d;border:1px solid #d8cabe}.ph-select{width:100%;padding:11px;border:1px solid #d8cabe;border-radius:12px;background:#fff;font:inherit}.ph-notice{position:fixed;left:16px;right:16px;bottom:86px;z-index:10001;background:#fffaf5;border:2px solid #d9794f;border-radius:18px;padding:15px;box-shadow:0 20px 60px rgba(30,20,10,.2);display:none}.ph-notice.show{display:block}.ph-test{font-size:.95rem;line-height:1.55}.ph-ok{font-weight:800}.ph-warn{font-weight:800}`;document.head.appendChild(s)}

  async function connect(){
    if(connecting)return connecting;
    if(!C.SUPABASE_URL||!C.SUPABASE_ANON_KEY)return false;
    connecting=(async()=>{try{const mod=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');sb=mod.createClient(C.SUPABASE_URL,C.SUPABASE_ANON_KEY);const r=await sb.auth.getSession();user=r.data?.session?.user||null;sb.auth.onAuthStateChange((_e,s)=>{user=s?.user||null;if(user)syncAll()});if(user)await syncAll();return!!user}catch(_){sb=null;return false}finally{connecting=null}})();return connecting;
  }

  function localSessionKey(s,i){const raw=(user?.id||'device')+'|'+(s.date||'')+'|'+i+'|'+JSON.stringify((s.results||[]).map(r=>r.name||r.game_id));let h=2166136261;for(let i=0;i<raw.length;i++){h^=raw.charCodeAt(i);h=Math.imul(h,16777619)}return `session-${(h>>>0).toString(16)}`}
  async function syncHistory(){
    const history=read('ccner-history',[]);let ok=true;
    for(let i=0;i<history.length;i++){const s=history[i];try{const key=localSessionKey(s,i);let q=await sb.from('cognitive_sessions').select('id').eq('user_id',user.id).eq('metadata->>client_session_key',key).limit(1);if(q.error)throw q.error;let session=q.data?.[0];if(!session){const ins=await sb.from('cognitive_sessions').insert({user_id:user.id,started_at:s.date,completed_at:s.date,score:Number(s.score||0),accuracy:Number(s.accuracy||0),average_response_seconds:Number(s.avgTime||0),difficulty_level:Math.min(10,Math.max(1,Number(s.level||1))),games_completed:(s.results||[]).filter(r=>!r.skipped).length,metadata:{source:'ccner',client_session_key:key,device:localStorage.getItem('ccner-p2-device')||'unknown'}}).select('id').single();if(ins.error)throw ins.error;session=ins.data}const results=(s.results||[]).filter(r=>!r.skipped).map((r,j)=>({user_id:user.id,session_id:session.id,game_id:`${key}-g-${j}-${String(r.name||'game').toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,40)}`,game_name:r.name||'Game',category:r.category||r.name||'Game',correct:Number(r.correct||0)>0,score:Number(r.score||0),response_seconds:Number(r.seconds||0),difficulty_level:Math.min(10,Math.max(1,Number(r.difficulty||s.level||1)))}));for(const r of results){const ex=await sb.from('game_results').select('id').eq('user_id',user.id).eq('game_id',r.game_id).limit(1);if(ex.error)throw ex.error;if(!ex.data?.length){const ins=await sb.from('game_results').insert(r);if(ins.error)throw ins.error}}}catch(_){ok=false}}
    return ok;
  }

  async function applyReminder(item){
    const p={...(item.payload||{})};const cid=clientId(p,'rem');let rows=reminders();let local=rows.find(x=>x.id===p.id||x.client_id===cid);if(!local){local={...p,id:p.id||uuid(),client_id:cid};rows.push(local);saveReminders(rows)}else{local={...local,...p,client_id:cid};rows=rows.map(x=>x.id===local.id?local:x);saveReminders(rows)}
    if(item.operation==='delete'){const target=await sb.from('reminders').select('id').eq('user_id',user.id).eq('client_id',cid).limit(1);if(target.error)throw target.error;if(target.data?.[0]){const d=await sb.from('reminders').delete().eq('id',target.data[0].id).eq('user_id',user.id);if(d.error)throw d.error}if(window.CCNERNotifications)await window.CCNERNotifications.remove(local.id);return}
    const payload={user_id:user.id,client_id:cid,title:String(local.title||'Reminder').slice(0,200),reminder_time:String(local.time||local.reminder_time||'00:00').slice(0,5),repeat_rule:local.repeat||local.repeat_rule||'daily',active:local.enabled!==false&&local.active!==false,kind:local.kind||classify(local.title),details:{source:'ccner',client_id:cid},created_by:user.id,timezone:local.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Kolkata',days_of_week:Array.isArray(local.days_of_week)?local.days_of_week:[0,1,2,3,4,5,6],delivery_status:'scheduled'};
    const up=await sb.from('reminders').upsert(payload,{onConflict:'user_id,client_id'});if(up.error)throw up.error;if(window.CCNERNotifications){if(payload.active)await window.CCNERNotifications.upsert({...local,enabled:true});else await window.CCNERNotifications.remove(local.id)}
  }
  async function applyTask(item){
    const p={...(item.payload||{})};const cid=clientId(p,'task');let rows=tasks();let local=rows.find(x=>x.id===p.id||x.client_id===cid);if(!local){local={...p,id:p.id||uuid(),client_id:cid};rows.push(local);saveTasks(rows)}else{local={...local,...p,client_id:cid};rows=rows.map(x=>x.id===local.id?local:x);saveTasks(rows)}
    if(item.operation==='delete'){const target=await sb.from('daily_tasks').select('id').eq('user_id',user.id).eq('client_id',cid).limit(1);if(target.error)throw target.error;if(target.data?.[0]){const d=await sb.from('daily_tasks').delete().eq('id',target.data[0].id).eq('user_id',user.id);if(d.error)throw d.error}return}
    const payload={user_id:user.id,client_id:cid,title:String(local.title||'Task').slice(0,200),task_date:local.task_date||new Date().toISOString().slice(0,10),completed:!!local.completed,completed_at:local.completedAt||local.completed_at||null};const up=await sb.from('daily_tasks').upsert(payload,{onConflict:'user_id,client_id'});if(up.error)throw up.error;
  }
  async function applyProfile(item){const p=item.payload||{};const up=await sb.from('profiles').upsert({user_id:user.id,display_name:p.name||p.display_name||'',preferred_language:p.preferredLanguage||p.preferred_language||'en-IN',caregiver_name:p.caregiverName||p.caregiver_name||null,updated_at:now()},{onConflict:'user_id'});if(up.error)throw up.error}
  async function applyTrigger(item){const p=item.payload||{};if(p.reminderId){const r=reminders().find(x=>x.id===p.reminderId);if(r){const local={...r,lastNotifiedDate:String(p.triggeredAt||now()).slice(0,10)};saveReminders(reminders().map(x=>x.id===r.id?local:x));const q=await sb.from('reminders').select('id').eq('user_id',user.id).eq('client_id',r.client_id||r.id).limit(1);if(q.data?.[0]){const u=await sb.from('reminders').update({last_triggered_at:p.triggeredAt,delivery_status:'delivered',acknowledged_at:null}).eq('id',q.data[0].id).eq('user_id',user.id);if(u.error)throw u.error}}}}
  async function applyQueueItem(item){const t=String(item.type||item.entity_type||'');if(t==='reminder'||t==='reminder.created'||t==='reminder.updated'||t==='reminder.deleted')return applyReminder({...item,operation:t.endsWith('deleted')?'delete':'upsert'});if(t==='task'||t==='task.created'||t==='task.updated'||t==='task.deleted')return applyTask({...item,operation:t.endsWith('deleted')?'delete':'upsert'});if(t==='profile'||t==='profile.updated')return applyProfile(item);if(t==='reminder_trigger')return applyTrigger(item);return true}

  async function flushQueue(){
    if(!sb||!user||navigator.onLine===false)return false;let q=queue();let all=true;
    for(const item of q){if(item.status==='synced')continue;try{await applyQueueItem(item);const ins=await sb.from('sync_queue').upsert({user_id:user.id,client_event_id:String(item.id||uuid()),entity_type:String(item.type||item.entity_type||'unknown'),operation:String(item.operation||'upsert'),payload:item.payload||{},client_created_at:item.createdAt||now(),synced_at:now(),processed_at:now(),attempts:Number(item.attempts||0)+1},{onConflict:'user_id,client_event_id'});if(ins.error)throw ins.error;item.status='synced';item.syncedAt=now();item.attempts=Number(item.attempts||0)+1;item.lastError=null}catch(e){item.attempts=Number(item.attempts||0)+1;item.lastError=String(e?.message||e);all=false}}
    saveQueue(q);if(all)localStorage.setItem('ccner-p2-sync-complete',now());return all;
  }

  async function syncAll(){if(!sb||!user||navigator.onLine===false)return false;const historyOk=await syncHistory();const queueOk=await flushQueue();if(historyOk&&queueOk){localStorage.setItem('ccner-p2-session-sync',now());await audit('sync.completed',{history:true,queue:true})}return historyOk&&queueOk}
  async function audit(action,metadata={}){if(!sb||!user||navigator.onLine===false)return;try{await sb.from('audit_log').insert({user_id:user.id,action,entity_type:metadata.entityType||null,entity_id:metadata.entityId||null,metadata:{...metadata,appVersion:'0.9.12'}})}catch(_){} }
  async function queueEntity(type,operation,payload){const q=queue();q.push({id:uuid(),type,operation,payload,createdAt:now(),status:'pending',attempts:0});saveQueue(q);if(user&&navigator.onLine!==false)await flushQueue()}

  async function requestNotifications(){if(window.CCNERNotifications)return window.CCNERNotifications.request();if('Notification'in window){if(Notification.permission==='granted')return true;if(Notification.permission==='denied')return false;return(await Notification.requestPermission())==='granted'}return false}
  function notice(title,message){let n=document.getElementById('phNotice');if(!n){n=document.createElement('div');n.id='phNotice';n.className='ph-notice';document.body.appendChild(n)}n.classList.add('show');n.innerHTML='<strong>'+esc(title)+'</strong><p style="margin:6px 0 0">'+esc(message)+'</p>';setTimeout(()=>n.classList.remove('show'),12000);if('Notification'in window&&Notification.permission==='granted'){try{new Notification(title,{body:message,tag:'ccner-reminder'})}catch(_){} }}
  function reminderDue(r,d){if(!r||r.enabled===false)return false;const t=String(r.time||r.reminder_time||'');if(!/^\\d{2}:\\d{2}$/.test(t))return false;return d.getHours()===Number(t.slice(0,2))&&d.getMinutes()===Number(t.slice(3))&&r.lastNotifiedDate!==d.toISOString().slice(0,10)}
  async function checkReminders(){const d=new Date();for(const r of reminders()){if(!reminderDue(r,d))continue;r.lastNotifiedDate=d.toISOString().slice(0,10);saveReminders(reminders().map(x=>x.id===r.id?r:x));const msg=(r.kind||classify(r.title))==='medicine'?'It is time for your medicine reminder.':(r.kind||classify(r.title))==='hydration'?'Time for a little water.':(r.kind||classify(r.title))==='appointment'?'You have an appointment reminder.':'Time for your planned daily activity.';notice(r.title,msg);await queueEntity('reminder_trigger','insert',{reminderId:r.id,kind:r.kind||classify(r.title),title:r.title,triggeredAt:d.toISOString()})}}

  function normalize(){const rs=reminders().map(r=>({...r,kind:r.kind||classify(r.title),enabled:r.enabled!==false,client_id:r.client_id||r.id||uuid()}));saveReminders(rs);const ts=tasks().map(t=>({...t,client_id:t.client_id||t.id||uuid()}));saveTasks(ts);return rs}
  function patchReminderForm(){const form=document.getElementById('p1ReminderForm');if(!form||form.dataset.hardened)return;form.dataset.hardened='1';const label=document.createElement('label');label.innerHTML='<span style="display:block;margin-bottom:4px">Type</span><select name="kind" class="ph-select"><option value="medicine">💊 Medicine</option><option value="hydration">💧 Hydration</option><option value="daily_activity">📅 Daily activity</option><option value="appointment">🏥 Medical appointment</option><option value="general">General</option></select>';form.insertBefore(label,form.querySelector('.p1-actions'));form.addEventListener('submit',()=>setTimeout(async()=>{const rows=normalize();const r=rows.at(-1);if(r){r.kind=form.kind?.value||r.kind;r.enabled=true;r.client_id=r.client_id||r.id||uuid();saveReminders(rows);await queueEntity('reminder','upsert',{...r,client_id:r.client_id});if(window.CCNERNotifications)await window.CCNERNotifications.upsert(r)}},0))}

  async function caregiverAlerts(){if(!sb||!user||navigator.onLine===false)return[];const r=await sb.from('caregiver_alerts').select('id,patient_id,caregiver_id,type,severity,title,message,acknowledged_at,created_at').or(`caregiver_id.eq.${user.id},patient_id.eq.${user.id}`).is('acknowledged_at',null).order('created_at',{ascending:false}).limit(50);return r.error?[]:(r.data||[])}
  async function createAlerts(){if(!sb||!user||navigator.onLine===false)return;const h=read('ccner-history',[]);const last=h.at(-1),prev=h.at(-2);if(!last)return;const links=await sb.from('caregiver_links').select('caregiver_user_id').eq('patient_user_id',user.id).eq('status','active');if(links.error||!links.data?.length)return;const flags=[];if(prev&&Number(last.score||0)<=Number(prev.score||0)-10)flags.push(['performance_change','attention','Recent performance change','The latest training score is at least 10 points lower than the previous session. Review the broader pattern rather than drawing a clinical conclusion.']);for(const f of flags)for(const l of links.data){const ex=await sb.from('caregiver_alerts').select('id').eq('patient_id',user.id).eq('caregiver_id',l.caregiver_user_id).eq('type',f[0]).is('acknowledged_at',null).limit(1);if(!ex.data?.length)await sb.from('caregiver_alerts').insert({patient_id:user.id,caregiver_id:l.caregiver_user_id,type:f[0],severity:f[1],title:f[2],message:f[3],source_session_id:null})}}
  async function openCaregiverPortal(){if(!sb||!user){alert('Please sign in first.');return}const links=await sb.from('caregiver_links').select('patient_user_id,status,role').eq('caregiver_user_id',user.id).eq('status','active');if(links.error){alert('Caregiver access could not be loaded.');return}const ids=(links.data||[]).map(x=>x.patient_user_id);const p=ids.length?await sb.from('profiles').select('user_id,display_name,preferred_language').in('user_id',ids):{data:[]};const alerts=await caregiverAlerts();const panel=document.createElement('section');panel.className='p2-panel';panel.innerHTML='<div class="p2-sheet"><button class="p2-close" aria-label="Close">×</button><span class="p2-eyebrow">SECURE CAREGIVER ACCESS</span><h2>My linked patients</h2><p class="p2-sub">Only active caregiver links are shown.</p><div class="ph-card"><strong>Patients</strong>'+(p.data?.length?p.data.map(x=>`<div class="ph-row"><div><strong>${esc(x.display_name||'Participant')}</strong><small>Language: ${esc(x.preferred_language||'—')}</small></div><span class="ph-badge">Active link</span></div>`).join(''):'<p class="p2-muted">No active patient links.</p>')+'</div><div class="ph-card"><strong>Open alerts</strong>'+(alerts.length?alerts.map(a=>`<div class="ph-alert ${esc(a.severity)}"><strong>${esc(a.title)}</strong><p>${esc(a.message)}</p><small>${new Date(a.created_at).toLocaleString()}</small><div class="ph-actions"><button class="ph-btn secondary" data-ack="${a.id}">Acknowledge</button></div></div>`).join(''):'<p class="p2-muted">No open caregiver alerts.</p>')+'</div></div>';document.body.appendChild(panel);panel.querySelector('.p2-close').onclick=()=>panel.remove();panel.querySelectorAll('[data-ack]').forEach(b=>b.onclick=async()=>{const r=await sb.from('caregiver_alerts').update({acknowledged_at:now()}).eq('id',b.dataset.ack).eq('caregiver_id',user.id);if(!r.error)b.closest('.ph-alert')?.remove()})}
  function addCaregiverButton(){const home=document.getElementById('homeView');if(!home||document.getElementById('phCaregiverButton'))return;const b=document.createElement('button');b.id='phCaregiverButton';b.className='p2-btn p2-dashboard-launch';b.textContent='👩‍⚕️ Caregiver secure portal';b.onclick=openCaregiverPortal;home.querySelector('.p2-dashboard-launch')?.insertAdjacentElement('afterend',b)||home.appendChild(b)}
  function boot(){injectStyle();normalize();patchReminderForm();addCaregiverButton();connect();setTimeout(patchReminderForm,1200);setTimeout(()=>window.CCNERNotifications?.syncAll(),1500)}
  window.addEventListener('online',()=>{window.CCNERNotifications?.syncAll();syncAll()});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden){checkReminders();syncAll()}});
  setInterval(checkReminders,15000);setInterval(()=>{if(navigator.onLine!==false)syncAll()},60000);setInterval(patchReminderForm,1000);
  window.CCNERProductionHardening={syncAll,flushQueue,queueEntity,requestNotifications,checkReminders,openCaregiverPortal,audit};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
